S = "Hakeem Force Academy"
QS = [
(S, "What is the other name of the Battle of Ahzab?", ["Battle of Khandaq", "Battle of Uhud", "Battle of Badr", "Battle of Hunain"], 0, "The Battle of Ahzab (the Confederates) is also called the Battle of Khandaq (the Trench) because the Muslims dug a trench around Madinah. It was fought in 5 AH.", "The trench was dug on the suggestion of Hazrat Salman Farsi (RA).", 1),
(S, "What is the shaving of the head during Hajj called?", ["Halq", "Ramy", "Tawaf", "Sai"], 0, "Halq is shaving the whole head, and Qasr is trimming the hair. One of them is done to come out of the state of Ihram.", "Women only trim a small portion of their hair (Taqsir).", 1),
(S, "Which is the smallest country in the world by area?", ["Vatican City", "Monaco", "San Marino", "Liechtenstein"], 0, "Vatican City covers about 0.44 square km, the smallest independent state in the world. Monaco is the second smallest.", "Vatican City is an enclave inside the city of Rome, Italy.", 2),
(S, "What is the source of the Yellow River (Huang He)?", ["Bayan Har Mountains in Qinghai, China", "Himalayas in Nepal", "Altai Mountains in Mongolia", "Tian Shan range in Xinjiang"], 0, "The Yellow River rises in the Bayan Har Mountains of Qinghai Province, China. It then flows east into the Bohai Sea.", "The river is about 5,464 km long, though sources differ on the exact figure.", 1),
(S, "Which word is closest in meaning to ADHERENT?", ["Follower", "Opponent", "Stranger", "Critic"], 0, "An adherent is a supporter or follower of a person, party or idea.", "The verb adhere means to stick to or stay loyal to something.", 1),
(S, "Which word is closest in meaning to COMPASSION?", ["Sympathy", "Cruelty", "Anger", "Envy"], 0, "Compassion is a feeling of pity and concern for the suffering of others, which is sympathy.", "Its opposite is callousness or cruelty.", 1),
(S, "Which word is closest in meaning to CONSENT?", ["Agreement", "Refusal", "Dispute", "Delay"], 0, "Consent means permission or agreement to something.", "Its opposite is dissent or refusal.", 1),
(S, "Which word is closest in meaning to DIVERSITY?", ["Variety", "Sameness", "Unity", "Scarcity"], 0, "Diversity means a range of different things or people, which is variety.", "Its opposite is uniformity.", 1),
(S, "Which word is closest in meaning to EXCITING?", ["Thrilling", "Boring", "Dull", "Gloomy"], 0, "Exciting means causing great enthusiasm or eagerness, which is thrilling.", "The word excite comes from the Latin excitare, meaning to rouse.", 1),
(S, "Which word is closest in meaning to EXTREMELY?", ["Exceedingly", "Slightly", "Hardly", "Rarely"], 0, "Extremely means to a very high degree, which is exceedingly.", "Words such as utterly and highly are also similar in sense.", 1),
(S, "Which word is closest in meaning to FLOURISH?", ["Thrive", "Wither", "Decline", "Hide"], 0, "To flourish is to grow and develop in a healthy, successful way, which is to thrive.", "Its opposite is to decay or wither.", 1),
(S, "Which word is closest in meaning to HERITAGE?", ["Legacy", "Invention", "Fashion", "Income"], 0, "Heritage is what is passed down from earlier generations, such as traditions and property, which is a legacy.", "UNESCO lists World Heritage Sites such as Moenjodaro and Taxila in Pakistan.", 1),
(S, "Which word is closest in meaning to HIERARCHY?", ["Ranking order", "Equality", "Confusion", "Freedom"], 0, "A hierarchy is a system in which people or things are arranged in order of rank or importance.", "The army rank structure is a typical hierarchy.", 1),
(S, "Which word is closest in meaning to IMPAIR?", ["Weaken", "Improve", "Repair", "Celebrate"], 0, "To impair is to damage or weaken something so that it works less well. The candidate answer Ridicule has a different meaning.", "Its opposite is to enhance or improve.", 1),
(S, "Which word is closest in meaning to INDIFFERENCE?", ["Apathy", "Enthusiasm", "Passion", "Concern"], 0, "Indifference is a lack of interest or concern, which is apathy.", "Its opposite is concern or enthusiasm.", 1),
(S, "Which word is closest in meaning to INHABITANT?", ["Resident", "Visitor", "Tourist", "Stranger"], 0, "An inhabitant is a person who lives permanently in a place, which is a resident.", "The verb inhabit means to live in a place.", 1),
(S, "Which word is closest in meaning to LAXITY?", ["Slackness", "Strictness", "Diligence", "Firmness"], 0, "Laxity means lack of strictness or care, which is slackness.", "Its opposite is rigour or strictness.", 1),
(S, "Which word is closest in meaning to LEISURE?", ["Free time", "Hard labour", "Duty", "Hurry"], 0, "Leisure is time free from work or duties, which is free time.", "The word comes from the Old French leisir, meaning to be permitted.", 1),
(S, "Which word is closest in meaning to MALICIOUS?", ["Spiteful", "Kind", "Generous", "Innocent"], 0, "Malicious means intending to harm others, which is spiteful.", "Its opposite is benevolent.", 1),
(S, "Which word is closest in meaning to MEDIATE?", ["Arbitrate", "Quarrel", "Ignore", "Postpone"], 0, "To mediate is to step in between two sides in a dispute to settle it, which is to arbitrate.", "A mediator is a neutral person who helps two parties reach agreement.", 1),
(S, "Which word is closest in meaning to OPPRESS?", ["Persecute", "Support", "Free", "Reward"], 0, "To oppress is to keep people down by cruel or unjust use of power, which is to persecute.", "Its opposite is to liberate.", 1),
(S, "Which word is closest in meaning to PRECEDING?", ["Previous", "Following", "Final", "Next"], 0, "Preceding means coming before in time or order, which is previous.", "Its opposite is succeeding or following.", 1),
(S, "Which word is closest in meaning to PREVENT?", ["Avert", "Allow", "Encourage", "Begin"], 0, "To prevent is to stop something from happening, which is to avert.", "Hinder and thwart are also close in meaning.", 1),
(S, "Which word is closest in meaning to PROMINENT?", ["Eminent", "Hidden", "Minor", "Obscure"], 0, "Prominent means well known or important, which is eminent.", "It can also mean easily seen or standing out.", 1),
(S, "Which word is closest in meaning to RESENTMENT?", ["Bitterness", "Gratitude", "Delight", "Calmness"], 0, "Resentment is a feeling of bitter anger about unfair treatment, which is bitterness.", "Its opposite is gratitude.", 1),
(S, "Which word is closest in meaning to SPLENDID?", ["Magnificent", "Poor", "Ordinary", "Weak"], 0, "Splendid means very impressive or excellent, which is magnificent.", "Splendid comes from the Latin splendere, to shine.", 1),
(S, "Which word is closest in meaning to TIMID?", ["Shy", "Bold", "Fierce", "Reckless"], 0, "Timid means lacking courage or confidence, which is shy.", "Its opposite is bold or daring.", 1),
(S, "Which word is closest in meaning to TOTALLY?", ["Completely", "Partly", "Barely", "Sometimes"], 0, "Totally means in every way or to the full extent, which is completely or entirely.", "Utterly and wholly are other close words.", 1),
(S, "Which word is closest in meaning to TYRANT?", ["Despot", "Hero", "Servant", "Citizen"], 0, "A tyrant is a ruler who uses power in a cruel and unjust way, which is a despot.", "Its opposite in sense is a benevolent ruler.", 1),
(S, "Which is the tallest animal living on land?", ["Giraffe", "African elephant", "Camel", "Ostrich"], 0, "An adult giraffe can reach about 5 to 5.5 metres in height. No other land animal is taller.", "Giraffes mostly eat leaves from acacia trees.", 1),
(S, "What is the period between a person's death and the Day of Judgment called?", ["Barzakh", "Qiyamah", "Mahshar", "Sirat"], 0, "Barzakh is the intermediate stage between death and resurrection mentioned in the Quran (Surah Al-Muminun 23:100).", "The grave life is usually described as part of the Barzakh.", 1),
(S, "What is the title (laqab) of Hazrat Adam (AS)?", ["Abul Bashar", "Khalilullah", "Kaleemullah", "Ruhullah"], 0, "Hazrat Adam (AS) is called Abul Bashar, the father of mankind. He is also called Safiullah.", "He was the first human and the first prophet in Islamic belief.", 1),
(S, "What is the title of Hazrat Isa (AS)?", ["Ruhullah", "Khalilullah", "Kaleemullah", "Zabihullah"], 0, "Hazrat Isa (AS) is called Ruhullah (Spirit of Allah) and also Al-Masih. Khalilullah is for Ibrahim, Kaleemullah for Musa and Zabihullah for Ismail (AS).", "He was born miraculously to Hazrat Maryam (AS) without a father.", 1),
(S, "What is the title of Hazrat Jibrael (AS)?", ["Ruh ul Amin", "Ruhullah", "Safiullah", "Kaleemullah"], 0, "Hazrat Jibrael (AS) is called Ruh ul Amin (the Trustworthy Spirit) in the Quran, and also Ruh ul Quds.", "He brought revelation to all prophets, including the Holy Prophet (PBUH).", 1),
(S, "What is the length of the Line of Control (LoC) between Pakistan and India in Kashmir in kilometres, as most commonly given?", ["About 740 km", "About 1,046 km", "About 2,430 km", "About 560 km"], 0, "The Line of Control was set after the 1971 war and the Simla Agreement of 1972. It is most commonly given as about 740 km.", "Sources differ, with some giving up to 776 km.", 1),
(S, "How many bones are there in the adult human body?", ["206", "212", "198", "300"], 0, "An adult skeleton has 206 bones. A newborn has about 300 which fuse as the child grows.", "The femur is the longest bone of the body.", 1),
]
